            'upload_spreadsheet'             => ['en' => 'Upload a spreadsheet document',   'sw' => 'Pakia hati ya lahajedwali'],
            'json_payload'                   => ['en' => 'JSON Payload',                    'sw' => 'Mzigo wa JSON'],
            'upload_file'                    => ['en' => 'Upload File',                     'sw' => 'Pakia Faili'],
            'drag_drop_blurb'                => ['en' => 'Drag and drop your file here or click to browse', 'sw' => 'Buruta na uweke faili yako hapa au bonyeza kutafuta'],
            'preview_import'                 => ['en' => 'Preview Import',                  'sw' => 'Hakikisha Uingizaji'],
            'parsing'                        => ['en' => 'Parsing...',                      'sw' => 'Inachakata...'],
            'confirm_import'                 => ['en' => 'Confirm Import',                  'sw' => 'Thibitisha Uingizaji'],
        ];

        $count = 0;

        foreach ($translations as $key => $text) {
            TranslationLanguageLine::updateOrCreate(
                ['group' => 'system', 'key' => $key],
                ['text' => $text]
            );
            $count++;
        }

        $this->command->info("System translations seeded: {$count} keys (group: system)");
    }
}
